    int checks;Context c;MainActivity a;ActivityMonitor weCom;
    void launchAttendance(String key){main(()->a.attendanceLaunch(key,new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setPackage("com.tencent.wework")));}
    void check(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}
