    void fits(String page)throws Exception{idle();main(()->{ScrollView scroll=(ScrollView)a.body.getParent();int used=a.body.getPaddingTop()+a.body.getPaddingBottom();for(int i=0;i<a.body.getChildCount();i++){View v=a.body.getChildAt(i);ViewGroup.MarginLayoutParams p=(ViewGroup.MarginLayoutParams)v.getLayoutParams();used+=v.getMeasuredHeight()+p.topMargin+p.bottomMargin;}check(used<=scroll.getHeight(),page+" main content fits viewport; used="+used+", available="+scroll.getHeight());});}
